import json
import logging
import re
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass, field

from pydantic import ValidationError

from ..config import get_settings
from ..errors import AppError
from ..schemas import CopyOutput, CreativeSettings, Platform, ProductInput, Tone
from . import prompts
from .. import tracing
from .llm.base import LLMProvider
from .llm.demo import demo_copy, demo_section
from .llm.ollama import OllamaProvider

log = logging.getLogger("sellcraft.copy")

REQUIRED_NONEMPTY = ("product_title", "short_description", "full_description", "social_caption",
                     "video_hook", "voiceover_script")


@dataclass
class CopyResult:
    copy: CopyOutput
    source: str  # "ollama:<model>" | "demo"
    usage: dict = field(default_factory=dict)


def _as_list(v) -> list[str]:
    if v is None:
        return []
    if isinstance(v, str):
        return [p.strip(" -•\t") for p in re.split(r"[\n;]|(?<=\.)\s", v) if p.strip(" -•\t")]
    return [str(x).strip() for x in v if str(x).strip()]


def _as_str(v) -> str:
    if v is None:
        return ""
    if isinstance(v, (list, tuple)):
        return " ".join(str(x) for x in v)
    return str(v).strip()


def normalize(data: dict, kinds: dict[str, str] | None = None) -> dict:
    """Coerce common small-model slips (list vs string) before Pydantic validation."""
    out = {}
    for k, v in data.items():
        kind = (kinds or prompts.CORE_FIELDS).get(k)
        if kind == "list":
            out[k] = _as_list(v)
        elif kind == "str":
            out[k] = _as_str(v)
        elif k == "platform_outputs" and isinstance(v, dict):
            out[k] = {}
            for pname, fields in v.items():
                try:
                    spec = prompts.PLATFORM_FIELDS[Platform(pname)]
                    on_progress(dict(results), len(jobs))
        return results

    def _partial(self, results: dict) -> CopyOutput | None:
        """Best-effort copy from the chunks finished so far (not validated; shown read-only until complete)."""
        try:
            data, _, _ = self._merge(results)
            return CopyOutput.model_validate(normalize(_strip_placeholders(data)))
        except Exception:  # noqa: BLE001 - a partial view must never break the real run
            return None

    @staticmethod
    def _merge(results: dict):
        data: dict = {"platform_outputs": {}}
        usage = {"prompt_tokens": 0, "completion_tokens": 0, "latency_ms": 0, "chunks": len(results)}
        for name, r in results.items():
            if name.startswith("core:"):
                data.update(r.data)
            else:
                key = name.split(":", 1)[1]
                data["platform_outputs"][key] = r.data.get(key) or {}
            usage["prompt_tokens"] += r.usage.get("prompt_tokens") or 0
            usage["completion_tokens"] += r.usage.get("completion_tokens") or 0
            usage["latency_ms"] = max(usage["latency_ms"], r.latency_ms)
        return data, usage, next(iter(results.values())).model

    @staticmethod
    def _chunks_for(missing: list[str]) -> set[str]:
        out = set()
        for m in missing:
            if m.startswith("platform_outputs."):
                out.add("platform:" + m.split(".", 1)[1])
            else:
                out.update(f"core:{n}" for n, keys in enumerate(prompts.CORE_CHUNKS) if m in keys)
        return out

    def generate(self, product: ProductInput, settings: CreativeSettings, on_progress=None) -> CopyResult:
        """on_progress(partial_copy, done, total) is called as parallel parts finish."""
        if self.demo:
            return CopyResult(demo_copy(product, settings), "demo")
        jobs = self._chunks(product, settings)
        cb = None
        if on_progress:
            def cb(done_results, total):
                partial = self._partial(done_results)
                if partial is not None:
                    on_progress(partial, len(done_results), total)
        results = self._run(jobs, cb)
        data, usage, model = self._merge(results)
        try:
            copy = _validate(data, settings.platforms, strict=False)  # placeholders are stripped + flagged, never a re-run
        except AppError as e:
            if not e.retryable:
                raise
            log.warning("invalid model output (%s); redoing only the failed parts", e.code)
            redo = self._chunks_for(getattr(e, "missing", [])) or {j[0] for j in jobs}
            retry_jobs = [j for j in self._chunks(product, settings, f"\n\nA previous attempt had a problem: {e.message}. "
                                                  "Fill every field using only the facts.") if j[0] in redo]
            results.update(self._run(retry_jobs))
            data, usage, model = self._merge(results)
            copy = _validate(data, settings.platforms, strict=False)
        copy = self._post_check(copy, product)
        return CopyResult(copy, f"ollama:{model}", usage)

    def regenerate(self, current: CopyOutput, product: ProductInput, settings: CreativeSettings, *,
                   section: str | None, tone: Tone | None, instructions: str | None) -> CopyResult:
        settings = settings.model_copy(update={"tone": tone or settings.tone})
        if section is None:
            return self.generate(product, settings)
        if section.startswith("platform:"):
            try:
                Platform(section.split(":", 1)[1])
            except ValueError:
                raise AppError("bad_section", f"Unknown platform section '{section}'.")
        elif section not in prompts.CORE_FIELDS:
            raise AppError("bad_section", f"Unknown section '{section}'.")
        if self.demo:
            patch = demo_section(product, settings, section)
            usage = {}
            source = "demo"
        else:
            schema = prompts.build_schema(settings.platforms, section=section)
            user = prompts.build_user_prompt(product, settings, section=section, current=current, instructions=instructions)
            res = self._call(prompts.SYSTEM_PROMPT, user, schema)
            patch, usage, source = res.data, res.usage | {"latency_ms": res.latency_ms}, f"ollama:{res.model}"
        merged = current.model_copy(deep=True)
        if section.startswith("platform:"):
            key = section.split(":", 1)[1]
            spec = prompts.PLATFORM_FIELDS[Platform(key)]
            fields = patch.get(key) or {}
            norm = normalize({"platform_outputs": {key: fields}})["platform_outputs"].get(key, {})
            if not any(norm.values()):
                raise AppError("llm_incomplete_output", "The model returned nothing for that section.", retryable=True, status=502)
            merged.platform_outputs[key] = norm
        else:
            norm = normalize({section: patch.get(section)})
            val = norm[section]
            if val in ("", [], None):
                raise AppError("llm_incomplete_output", "The model returned nothing for that section.", retryable=True, status=502)
            data = merged.model_dump()
            data[section] = val
            merged = CopyOutput.model_validate(data)
        return CopyResult(self._post_check(merged, product), source, usage)

    @staticmethod
    def _post_check(copy: CopyOutput, product: ProductInput) -> CopyOutput:
        hits = forbidden_hits(copy, product.forbidden_words)
        flagged = [c for c in copy.claims_requiring_review if not c.startswith(("Forbidden word used:", "Not in your facts:", "Regulated claim"))]
        flagged += [f"Forbidden word used: {w}" for w in hits]
        flagged += [f"Not in your facts: \"{w}\". Remove it unless it's true." for w in risky_terms(copy, product)]
        flagged += [f"Regulated claim not in your facts: \"{w}\". Medical and cosmetic claims can create legal problems; remove it or check the rules that apply to you."
                    for w in regulated_terms(copy, product)]
        for w in hits:
            tracing.flag("forbidden", w)
        for w in risky_terms(copy, product):
            tracing.flag("risky", w)
        for w in regulated_terms(copy, product):
            tracing.flag("regulated", w)
        return copy.model_copy(update={"claims_requiring_review": flagged})
"""Job orchestration. Each stage updates real state in SQLite; the frontend polls it.

Pipeline (copy and video run CONCURRENTLY; they only meet at assembly):

    photos ──► studio images + motion clip ─────────────┐
    facts  ──► copy chunks (parallel LLM calls) ────────┴─► text overlays ─► final MP4

Runs inside FastAPI BackgroundTasks (threadpool): fine for a single-process prototype, but jobs die with the
process. Stage functions are independent so they can move to a worker later."""
import logging
import threading
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

from .. import db, tracing
from ..errors import AppError
from ..schemas import JobError, JobStatus, StageEntry
from .copy import CopyService
from .video import service as video

log = logging.getLogger("sellcraft.jobs")
_stage_lock = threading.Lock()


def _set_stage(job_id: str, stages: list[StageEntry], name: str, status: str, detail: str | None = None,
               notes: list[str] | None = None, progress: float | None = None) -> None:
    with _stage_lock:  # copy and video stages update this list from different threads
        now = db.now()
        for s in stages:
            if s.name == name:
                s.status, s.detail = status, detail
                s.notes = notes or s.notes
                s.progress = 1.0 if status in ("done", "skipped") else (progress if progress is not None else s.progress)
                s.finished_at = now if status != "running" else None
                break
        else:
            stages.append(StageEntry(name=name, status=status, detail=detail, notes=notes or [], started_at=now,
                                     progress=1.0 if status in ("done", "skipped") else (progress or 0.0),
                                     finished_at=now if status != "running" else None))
        db.update_job(job_id, stages=stages)


def _stage_copy(job_id, stages, copy_service):
    job = db.get_job(job_id)
    if job.copy_output is not None and job.copy_source:  # retry after a later-stage failure: keep the copy (and the seller's edits)
        _set_stage(job_id, stages, "copy", "done", job.copy_source)
        return
    db.update_job(job_id, status=JobStatus.generating_copy)
    _set_stage(job_id, stages, "copy", "running", progress=0.02)
    svc = copy_service or CopyService()
    def partial(copy, done, total):  # show finished parts right away; the UI keeps them read-only until complete
        db.update_job(job_id, copy_output=copy)
        _set_stage(job_id, stages, "copy", "running", f"{done}/{total} parts", progress=done / total)

    with tracing.span("llm", "copy.generate", model=getattr(svc.llm, "model", "demo")) as sp:
        result = svc.generate(job.product, job.settings, on_progress=partial)
        if sp is not None:
            for k, v in result.usage.items():
                sp.set_data(k, v)
    db.update_job(job_id, copy_output=result.copy, copy_source=result.source)
    _set_stage(job_id, stages, "copy", "done", result.source)


def _stage_video(job_id, stages):
    """Studio-enhance the photos and render the motion clip. Needs no copy, so it starts immediately."""
    job = db.get_job(job_id)
    _set_stage(job_id, stages, "video", "running", progress=0.02)
    video.clear_outputs(job_id, kinds=("clip", "video", "studio_image", "catalog_image", "cutout_image", "product_src", "deck_slide"))
    with tracing.span("video", "video.clip", style=job.settings.visual_style.value, photos=len(job.product.image_asset_ids)):
        res = video.render_clip(job, on_progress=lambda f: _set_stage(job_id, stages, "video", "running", progress=f))
    db.add_asset(kind="clip", mime="video/mp4", path=res.clip, method=res.method, job_id=job_id)
    for kind, path in res.images:
        db.add_asset(kind=kind, mime="image/png" if path.suffix == ".png" else "image/jpeg", path=path, method=res.method, job_id=job_id)
    _set_stage(job_id, stages, "video", "done", res.method, res.notes)
    return res.clip, res.method


def _stage_deck(job_id, stages):
    """Image deck from the refined product images + the (possibly edited) copy. A deck problem never blocks the video."""
    job = db.get_job(job_id)
    _set_stage(job_id, stages, "deck", "running", progress=0.3)
    for row in db.list_asset_rows(job_id, ("deck_slide",)):  # clear the previous deck first: new slides reuse the same file names
        Path(row["path"]).unlink(missing_ok=True)
        db.delete_asset(row["id"])
    try:
        with tracing.span("deck", "deck.build"):
            slides, notes = video.render_deck(job)
    except AppError as e:
        _set_stage(job_id, stages, "deck", "failed", e.code, notes=[e.message])
        return
    for sl in slides:
        db.add_asset(kind="deck_slide", mime="image/jpeg", path=sl.path, method=sl.kind, job_id=job_id)
    _set_stage(job_id, stages, "deck", "done", f"{len(slides)} slides", notes=notes)


def _stage_assembly(job_id, stages, clip, method):
    job = db.get_job(job_id)
    db.update_job(job_id, status=JobStatus.assembling_video)
    _set_stage(job_id, stages, "assembly", "running", progress=0.3)
    with tracing.span("video", "video.assemble"):
        out, probe = video.render_final(job, clip)
    db.add_asset(kind="video", mime="video/mp4", path=out, method=method, duration_seconds=probe.duration, job_id=job_id)
    _set_stage(job_id, stages, "assembly", "done", f"{probe.duration:.1f}s")


def run_generation(job_id: str, copy_service: CopyService | None = None) -> None:
    job = db.get_job(job_id)
    if job is None:
        return
    stages: list[StageEntry] = []
    try:
        with tracing.span("job", "generation", job_id=job_id, platforms=len(job.settings.platforms)):
            with ThreadPoolExecutor(max_workers=1) as pool:
                video_future = pool.submit(_stage_video, job_id, stages)  # runs while the LLM writes the copy
                try:
                    _stage_copy(job_id, stages, copy_service)
                except BaseException:
                    video_future.exception()  # let the video thread finish cleanly before reporting the copy error
                    raise
                db.update_job(job_id, status=JobStatus.generating_video)
                clip, method = video_future.result()
            if job.settings.voiceover:
                _set_stage(job_id, stages, "voiceover", "skipped", "Voiceover isn't enabled yet")
            _stage_deck(job_id, stages)
            _stage_assembly(job_id, stages, clip, method)
        db.update_job(job_id, status=JobStatus.completed)
    except AppError as e:
        _fail(job_id, stages, e.code, e.message, e.retryable)
    except Exception:  # noqa: BLE001 - never leak internals to the client
        log.exception("unexpected failure in job %s", job_id)
        _fail(job_id, stages, "internal_error", "Something went wrong on our side. Please retry.", True)


def run_reassembly(job_id: str) -> None:
    """Re-render only the text overlays after the seller edits the copy. Reuses the existing motion clip."""
    job = db.get_job(job_id)
    if job is None:
        return
    stages = [s for s in job.stages if s.name != "assembly"]
    try:
        rows = db.list_asset_rows(job_id, ("clip",))
        if not rows:
            raise AppError("clip_missing", "The base video is missing. Use Try again to rebuild it.", retryable=True, status=409)
        old = db.list_asset_rows(job_id, ("video",))
        stages = [s for s in stages if s.name != "deck"] + [s for s in job.stages if s.name == "deck"]
        _stage_deck(job_id, stages)  # the deck shows the title, benefits and CTA, so it follows the copy edits too
        _stage_assembly(job_id, stages, Path(rows[0]["path"]), rows[0]["method"])
        for r in old:  # keep the previous video until the new one is verified
            Path(r["path"]).unlink(missing_ok=True)
            db.delete_asset(r["id"])
        db.update_job(job_id, status=JobStatus.completed, error=None)
    except AppError as e:
        _fail(job_id, stages, e.code, e.message, e.retryable)
    except Exception:  # noqa: BLE001
        log.exception("unexpected failure re-assembling job %s", job_id)
        _fail(job_id, stages, "internal_error", "Something went wrong on our side. Please retry.", True)


def _fail(job_id, stages, code, message, retryable):
    for s in stages:
        if s.status == "running":
            _set_stage(job_id, stages, s.name, "failed", code)
    db.update_job(job_id, status=JobStatus.failed, error=JobError(code=code, message=message, retryable=retryable))
