// Plain (non-client) module so server components can use the same classes as <Button>.
export function cx(...c: (string | false | null | undefined)[]) {
  return c.filter(Boolean).join(" ");
}

export type Variant = "primary" | "secondary" | "ghost" | "danger" | "accent";
export type Size = "lg" | "md" | "sm";

/** Class string shared by <Button> and anchors styled as buttons, so every action looks the same. */
export function buttonClass(variant: Variant = "primary", size: Size = "md", extra?: string) {
  return cx(
    "inline-flex select-none items-center justify-center gap-2 rounded-[10px] font-medium tracking-[-0.01em] transition duration-150 active:scale-[0.97] disabled:cursor-not-allowed disabled:opacity-45 disabled:active:scale-100",
    size === "lg" && "min-h-13 px-6 text-base",
    size === "md" && "min-h-12 px-5 text-[15px]",
    size === "sm" && "min-h-11 px-3.5 text-sm",
    variant === "primary" && "bg-primary text-primary-fg shadow-card hover:opacity-90",
    variant === "accent" && "bg-accent text-accent-fg shadow-card hover:brightness-105",
    variant === "secondary" && "bg-surface text-foreground shadow-card ring-1 ring-border-strong hover:bg-surface-2",
    variant === "ghost" && "text-muted hover:bg-surface-2 hover:text-foreground",
    variant === "danger" && "bg-danger text-white hover:brightness-110",
    extra,
  );
}

"use client";
import { useQuery } from "@tanstack/react-query";
import { api } from "@/lib/api";
import { cx } from "./ui";

export function StatusBadge() {
  const { data, isError, isLoading } = useQuery({ queryKey: ["status"], queryFn: api.status, refetchInterval: 15000 });
  if (isLoading) return <div className="skeleton h-5 w-64 rounded-full" aria-label="Checking AI engine" />;
  if (isError || !data)
    return <Pill tone="bad" text="Backend offline" detail="Start the API: cd backend && .venv/bin/uvicorn app.main:app --port 8000" />;
  const l = data.llm;
  if (data.demo_mode) return <Pill tone="warn" text="Demo Mode" detail="Deterministic sample output, not a live model." />;
  if (!l.reachable) return <Pill tone="bad" text="Ollama not running" detail={l.hint} />;
  if (!l.model_available) return <Pill tone="warn" text={`Model ${l.model} not installed`} detail={l.hint} />;
  return <Pill tone="ok" text={`Open model ready: ${l.model}`} detail="Running locally through Ollama" />;
}

function Pill({ tone, text, detail }: { tone: "ok" | "warn" | "bad"; text: string; detail?: string }) {
  return (
    <div className="flex items-start gap-2.5 text-[13px]" role="status">
      <span className="relative mt-1.5 flex size-2 shrink-0">
        {tone === "ok" && <span className="absolute inline-flex size-full animate-ping rounded-full bg-ok opacity-50" />}
